VALUES ('77aa9a08-531b-4fd4-a5c7-97eb5edc1fad'::uuid, 'a0000000-0000-4000-8000-000000000401'::uuid, 'https://www.cms.gov/files/zip/rvu26c-updated-06-30-2026.zip', 'cms_pfs', 'CMS National Physician Fee Schedule Relative Value File RVU26C (July 2026, released 06/30/2026)', now(), 'sha256:rvu26c', TRUE, '{}'::jsonb, now())
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, extracted_at = now();

-- Supersede any earlier live rule for these keys (the CY2026 Final Rule
-- narrative extraction covered some of them). payer_rule must hold at
-- most one live row per key or fetchPayerRule's LIMIT 1 makes the answer
-- depend on row order.
