    ('OH', 'G0179'),
    ('NC', 'G0179'),
    ('SC', 'G0179'),
    ('OH', 'G0180'),
    ('NC', 'G0180'),
    ('SC', 'G0180'),
    ('OH', 'G0318'),
    ('NC', 'G0318'),
    ('SC', 'G0318')
  ) AS k(state, code)
 WHERE old.payer_id  = 'a0000000-0000-4000-8000-000000000401'::uuid
   AND old.state     = k.state
   AND old.code      = k.code
   AND old.attribute = 'covered'
   AND old.created_by <> 'extract:cms-rvu26c-2026-08'
   AND old.expiration_date IS NULL;

